#!/usr/bin/env bash
# Generated by Codex. Maintained secret-scanning entry point.
set -euo pipefail

REPO_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd -P)"
cd "$REPO_ROOT"

GITLEAKS_BIN="${GITLEAKS_BIN:-gitleaks}"
if [[ $# -gt 1 ]]; then
    echo "Usage: bash script/ci/check_secrets.sh [directory-to-scan]" >&2
    exit 2
fi

# Redact findings and disallow inline suppression comments. No report containing
# credential values is uploaded as an artifact.
if [[ $# -eq 1 ]]; then
    "$GITLEAKS_BIN" dir --config "$REPO_ROOT/.gitleaks.toml" \
        --redact=100 --verbose --no-banner --ignore-gitleaks-allow "$1"
else
    "$GITLEAKS_BIN" git --config "$REPO_ROOT/.gitleaks.toml" \
        --redact=100 --verbose --no-banner --ignore-gitleaks-allow --log-opts=--all "$REPO_ROOT"
fi
